const PILL_TAGS = new Set(["app-pill", "app-fancy-pill", "app-status-pill"]);
const OLD = "disableTooltip", NEW = "hideHint";

function walk(dir, out = []) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, out);
    else if (/\.(ts|html)$/.test(e.name)) out.push(p);
  }
  return out;
}
// tag name of the open element tag that contains index i, or null
function enclosingTag(text, i) {
  for (let j = i - 1; j >= 0; j--) {
    const c = text[j];
    if (c === ">") return null;
    if (c === "<") {
      const m = /^<([a-zA-Z][\w-]*)/.exec(text.slice(j, j + 80));
      return m ? m[1] : null;
    }
  }
  return null;
}
