    const i = m.index;
    const before = text[i - 1];
    let tag = null;
    if (before === ".") {
      const r = /(\w+)$/.exec(text.slice(Math.max(0, i - 40), i - 1));
      if (r && r[1] !== "this") tag = tagOfRef(text, r[1]);
    } else {
      tag = enclosingTag(text, i);
    }
    if (tag && PILL_TAGS.has(tag)) edits.push(i);
  }
  if (edits.length === 0) continue;
  let out = text;
  for (const i of edits.reverse()) out = out.slice(0, i) + NEW + out.slice(i + OLD.length);
  changed.push([file, edits.length]);
  if (write) fs.writeFileSync(file, out);
}
console.log(changed.map(([f, n]) => `${n}\t${path.relative(root, f)}`).join("\n"));
